return items.map(item => {
  const originalText = item.json.output;
  if (typeof originalText !== 'string') {
    return { json: { error: 'output no es texto', original: originalText } };
  }
  let cleaned = originalText.replace(/<[^>]*>/g, '').replace(/\t+/g, ' ').replace(/[ ]{2,}/g, ' ').trim();
  const minCharsPerPart = 500;
  const partes = [];
  const dividirPorPuntoMasCercano = (texto, cantidadPartes) => {
    const longPorParte = Math.floor(texto.length / cantidadPartes);
    const cortes = [];
    let lastIndex = 0;
    for (let i = 1; i < cantidadPartes; i++) {
      let corte = texto.lastIndexOf('.', i * longPorParte);
      if (corte === -1 || corte <= lastIndex + 50) {
        corte = texto.lastIndexOf(';', i * longPorParte);
        if (corte === -1 || corte <= lastIndex + 50) corte = texto.lastIndexOf(',', i * longPorParte);
        if (corte === -1 || corte <= lastIndex + 50) corte = texto.lastIndexOf(' ', i * longPorParte);
        if (corte === -1 || corte <= lastIndex + 50) corte = i * longPorParte;
      }
      cortes.push(corte);
      lastIndex = corte;
    }
    const secciones = [];
    let inicio = 0;
    for (let i = 0; i < cortes.length; i++) {
      secciones.push(texto.slice(inicio, cortes[i] + 1).trim());
      inicio = cortes[i] + 1;
    }
    secciones.push(texto.slice(inicio).trim());
    return secciones;
  };
  if (cleaned.length <= minCharsPerPart * 1.2) {
    partes.push(cleaned);
  } else if (cleaned.length <= minCharsPerPart * 2.2) {
    partes.push(...dividirPorPuntoMasCercano(cleaned, 2));
  } else {
    partes.push(...dividirPorPuntoMasCercano(cleaned, 3));
  }
  const output = {};
  partes.forEach((parte, index) => { output[`parte_${index + 1}`] = parte; });
  return { json: output };
});

